-- HU-26 · Páginas de políticas editables desde el panel (decisión 0011).
-- Cada página: dirección (slug), título, estilo (acordeón o texto corrido), orden, visible y una
-- lista de secciones {titulo, texto} en «texto seguro» (sin HTML). Límites también en lib/paginas.js.

create table public.paginas (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 60),
  titulo          text not null check (char_length(titulo) between 1 and 120),
  estilo          text not null default 'acordeon' check (estilo in ('acordeon', 'texto')),
  orden           integer not null default 0,
  visible         boolean not null default false,
  secciones       jsonb not null default '[]'::jsonb
                  check (jsonb_typeof(secciones) = 'array' and jsonb_array_length(secciones) <= 40),
  creado_en       timestamptz not null default now(),
  actualizado_en  timestamptz not null default now()
);

create index paginas_orden_idx on public.paginas (orden) where visible;
create trigger paginas_touch before update on public.paginas for each row execute function public.tocar_actualizado_en();

-- RLS: el público solo lee las visibles; el administrador autenticado hace todo.
alter table public.paginas enable row level security;
create policy paginas_publico on public.paginas for select to anon using (visible);
create policy paginas_admin   on public.paginas for all to authenticated using (true) with check (true);

-- Borradores iniciales OCULTOS: base para que el dueño o su asesor los revisen antes de publicar.
insert into public.paginas (slug, titulo, estilo, orden, visible, secciones) values
  ('garantia', 'Garantía', 'acordeon', 1, false, $j$[{"titulo": "Aviso", "texto": "**Borrador por revisar:** texto base para validar con un asesor antes de publicar. Los valores entre corchetes [ ] se deben confirmar."}, {"titulo": "Duración de la garantía", "texto": "Los equipos **nuevos** tienen la garantía del fabricante, según la marca y el modelo.\n\nLos equipos **usados** (Grado A y Grado B) tienen una garantía de **[3] meses** contados desde la fecha de entrega, salvo que en la factura se indique otro plazo."}, {"titulo": "¿Qué cubre la garantía?", "texto": "- Fallas de funcionamiento de componentes internos (placa, memoria, almacenamiento, pantalla, teclado) que no se deban a mal uso.\n- Revisión técnica y, si aplica, reparación o cambio del componente.\n- Si la reparación no es posible, cambio por un equipo de características iguales o superiores, o devolución del dinero, según el Estatuto del Consumidor (Ley 1480 de 2011)."}, {"titulo": "Lo que no cubre la garantía", "texto": "- Golpes, caídas, humedad, líquidos o daños por sobrecarga eléctrica.\n- Equipos abiertos o reparados por terceros.\n- Software, virus, contraseñas olvidadas o pérdida de información.\n- Accesorios con desgaste normal (cargadores, baterías) fuera del plazo indicado."}, {"titulo": "Desgaste normal de un equipo usado", "texto": "Los equipos usados pueden tener marcas estéticas propias de su uso anterior, descritas en su **grado** (A o B). Estas marcas no son motivo de garantía."}, {"titulo": "Baterías", "texto": "La batería de los equipos usados tiene garantía de **[1] mes** desde la entrega. Su duración depende del uso y es normal que sea menor que la de un equipo nuevo."}, {"titulo": "Cómo hacer efectiva la garantía", "texto": "1. Escríbenos por WhatsApp con tu **número de factura** y una descripción de la falla.\n2. Lleva o envía el equipo a nuestra tienda en [Cali] con sus accesorios.\n3. Te informamos el diagnóstico en un plazo de hasta **[15] días hábiles**.\n\n**Recomendación:** haz una copia de tu información antes de entregar el equipo."}]$j$::jsonb),
  ('devolucion', 'Política de devolución', 'acordeon', 2, false, $j$[{"titulo": "Aviso", "texto": "**Borrador por revisar:** texto base para validar con un asesor antes de publicar. Los valores entre corchetes [ ] se deben confirmar."}, {"titulo": "Derecho de retracto", "texto": "Si compraste a distancia (por WhatsApp, teléfono o la web), puedes retractarte de la compra dentro de los **5 días hábiles** siguientes a la entrega, según el artículo 47 de la Ley 1480 de 2011."}, {"titulo": "Condiciones para devolver", "texto": "- El equipo debe estar en el mismo estado en que lo recibiste, con sus accesorios y empaque.\n- Sin daños, golpes ni modificaciones.\n- Presentando la factura o el comprobante de compra."}, {"titulo": "Costos de envío", "texto": "Los costos de transporte de la devolución corren por cuenta del cliente, salvo que el equipo tenga una falla o no corresponda a lo comprado."}, {"titulo": "Reembolso", "texto": "Una vez recibido y revisado el equipo, devolvemos el dinero por el mismo medio de pago en un plazo máximo de **30 días calendario**."}, {"titulo": "Cambios", "texto": "Si prefieres cambiar el equipo por otro, lo hacemos con gusto según disponibilidad; si hay diferencia de precio, se ajusta."}]$j$::jsonb),
  ('envios', 'Política de envíos', 'acordeon', 3, false, $j$[{"titulo": "Aviso", "texto": "**Borrador por revisar:** texto base para validar con un asesor antes de publicar. Los valores entre corchetes [ ] se deben confirmar."}, {"titulo": "Cobertura", "texto": "Enviamos a **todo el país** con transportadoras reconocidas. En [Cali] también puedes recoger en nuestra tienda."}, {"titulo": "Tiempos de entrega", "texto": "- Ciudades principales: **[1 a 3] días hábiles** después de confirmado el pago.\n- Otros municipios: **[3 a 6] días hábiles**.\n\nLos tiempos dependen de la transportadora y pueden variar en temporadas altas."}, {"titulo": "Costo del envío", "texto": "El costo se informa por WhatsApp antes de confirmar la compra, según la ciudad de destino y el tamaño del paquete."}, {"titulo": "Empaque y seguro", "texto": "Los equipos se envían bien protegidos y con **seguro** por su valor declarado."}, {"titulo": "Al recibir", "texto": "Revisa el paquete frente al mensajero. Si llega golpeado o abierto, déjalo anotado en la guía y escríbenos de inmediato con fotos."}]$j$::jsonb),
  ('terminos', 'Términos y condiciones', 'texto', 4, false, $j$[{"titulo": "Aviso", "texto": "**Borrador por revisar:** texto base para validar con un asesor antes de publicar. Los valores entre corchetes [ ] se deben confirmar."}, {"titulo": "Aceptación", "texto": "Al usar esta página y comprar con nosotros aceptas estos términos. [Razón social], NIT [número], con domicilio en [Cali, Valle del Cauca]."}, {"titulo": "Información de los productos", "texto": "Las fotos, características y precios publicados son informativos. Precios e inventario están **sujetos a cambios** sin previo aviso; el precio válido es el confirmado por nuestro asesor al cerrar la compra."}, {"titulo": "Proceso de compra", "texto": "La compra se acuerda por WhatsApp con un asesor, quien confirma disponibilidad, precio, forma de pago y envío. La venta se perfecciona con el pago y la emisión de la factura."}, {"titulo": "Medios de pago", "texto": "Aceptamos [transferencia bancaria, consignación, pago en tienda]. Nunca te pediremos claves ni códigos por WhatsApp."}, {"titulo": "Garantía, devoluciones y envíos", "texto": "Se rigen por nuestras políticas de **Garantía**, **Devolución** y **Envíos** publicadas en esta página, y por la Ley 1480 de 2011."}, {"titulo": "Propiedad intelectual", "texto": "Los textos, fotos y logos de esta página pertenecen a [Ventas Virtual Colombia] o a sus dueños y no se pueden usar sin autorización."}, {"titulo": "Contacto", "texto": "Para cualquier duda escríbenos por WhatsApp o visítanos en nuestra tienda."}]$j$::jsonb),
  ('privacidad', 'Política de privacidad', 'texto', 5, false, $j$[{"titulo": "Aviso", "texto": "**Borrador por revisar:** texto base para validar con un asesor antes de publicar. Los valores entre corchetes [ ] se deben confirmar."}, {"titulo": "Responsable del tratamiento", "texto": "[Razón social], NIT [número], con domicilio en [dirección], [Cali]. Correo: [correo]. Teléfono / WhatsApp: [número]."}, {"titulo": "Marco legal", "texto": "Esta política cumple la **Ley 1581 de 2012** y el **Decreto 1377 de 2013** (compilado en el Decreto 1074 de 2015) sobre protección de datos personales."}, {"titulo": "Qué datos tratamos y para qué", "texto": "Cuando nos escribes o compras, podemos tratar tu nombre, documento, teléfono, correo y dirección de entrega para:\n- Atender tu solicitud y cerrar la venta.\n- Facturar, enviar el pedido y gestionar garantías.\n- Enviarte información comercial, solo si nos autorizas.\n\nLa página **no usa cookies de seguimiento** ni guarda datos de quienes la visitan; solo cuenta visitas sin identificar a nadie."}, {"titulo": "Tus derechos", "texto": "Como titular puedes **conocer, actualizar, rectificar y suprimir** tus datos, solicitar prueba de la autorización, ser informado del uso que les damos, revocar la autorización y presentar quejas ante la Superintendencia de Industria y Comercio (SIC)."}, {"titulo": "Cómo ejercer tus derechos", "texto": "Escribe a [correo] o por WhatsApp indicando tu nombre, documento y tu solicitud. Respondemos consultas en máximo **10 días hábiles** y reclamos en máximo **15 días hábiles**."}, {"titulo": "Seguridad y vigencia", "texto": "Protegemos tus datos con medidas técnicas y administrativas razonables. Esta política rige desde [fecha] y los datos se conservan mientras sean necesarios para las finalidades descritas."}]$j$::jsonb);
